display.command:
python - <<'EOF'
import hashlib, os
def md5(p): return hashlib.md5(open(p,'rb').read()).hexdigest()
d1 = r'H:\test\lesson_n'
d2 = os.path.join(d1, '课设相关文档')
for d in (d1, d2):
    for f in os.listdir(d):
        p = os.path.join(d, f)
        if os.path.isfile(p) and (f.endswith('.pdf') or f.endswith('.skill')):
            print(md5(p), d, f, os.path.getsize(p))
EOF

